    // Initialize a new GraphPath object with the graph
    GraphPath<V,E> path = new GraphPath<>(graph);

    // Check if the tour set is empty
    if (tour.isEmpty()) {
        // Return an empty path if the tour set is empty
        return path;
    }

    // Find the first edge in the tour set
    E firstEdge = tour.iterator().next();

    // Find the start node of the first edge
    V startPoint = graph.getEdgeSource(firstEdge);

    // Add the start node to the path
    path.addVertex(startPoint);

    // Iterate over the tour set
    for (E edge : tour) {
        // Get the end node of the edge
        V endPoint = graph.getEdgeTarget(edge);

        // Add the end node to the path
        path.addVertex(endPoint);

        // Update the path with the edge
        path.addEdge(edge, graph.getEdgeSource(edge), graph.getEdgeTarget(edge));
    }

    // Return the graph path
    return path;
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour,Graph<V,E> graph) {
    GraphPath<V,E> path = new GraphPath<>();
    PriorityQueue<E> queue = new PriorityQueue<>((e1,e2) -> {
        if(graph.getEdgeWeight(e1,direction.OUT).equals(graph.getEdgeWeight(e2,direction.OUT)))
        {
            return graph.getEdgeWeight(e1,direction.IN)-graph.getEdgeWeight(e2,direction.IN);
        }
        return graph.getEdgeWeight(e1,direction.OUT)-graph.getEdgeWeight(e2,direction.OUT);
    });

    for (E e : tour) {
        if (graph.incidencePattern(e).hasEdge(direction.OUT)) {
            queue.add(e);
        }
    }

    for (int i = 0; i < graph.V()-1 && !queue.isEmpty(); i++) {
        E source = queue.poll();
        for (E target : graph.outNeighbors(source)) {
            if (!path.contains(target) && graph.incidencePattern(target).hasEdge(direction.OUT)) {
                path.add(target);
                queue.add(target);
            }
        }
    }

    path.add(path.vertices().iterator().next());
    return path;
}

