public static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices){
    if(graph==null || vertices==null) return false;
    if(vertices.isEmpty()) return true;
    Set<V> allNodes = new HashSet<>(graph.vertexSet());
    allNodes.retainAll(vertices);
    if(allNodes.size()<vertices.size()) return false;
    List<List<E>> adjList = new ArrayList<>();
    for(V v: graph.vertexSet()){
        adjList.add(new ArrayList<>());
        for(E e: graph.edgesOf(v)){
            adjList.get(v.ordinal()).add(e);
        }
    }
    for(V v: vertices){
        for(V w: adjList.get(v.ordinal())){
            for(V x: adjList.get(v.ordinal())){
                if(x==w || !adjList.get(x.ordinal()).contains(w)) continue;
                if(allNodes.contains(x)){
                    return false;
                }
            }
        }
    }
    return true;
}

private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (graph == null || vertices == null || graph.order() < vertices.size()) {
        throw new IllegalArgumentException("Input graph or vertices are null or graph is smaller than the number of vertices.");
    }

    Set<V> currentVertices = new HashSet<>(vertices);

    for (V vertex : vertices) {
        if (!currentVertices.contains(vertex)) {
            return false;
        }

        for (E edge : graph.incidentEdges(vertex)) {
            V neighbor = edge.getTarget();
            if (!currentVertices.contains(neighbor)) {
