public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null || path.isEmpty() || relativePath.isEmpty()) {
        throw new IllegalArgumentException("The path and relative path cannot be empty.");
    }

    // Replace all backslashes with forward slashes
    relativePath = relativePath.replace("\\\\", "/");

    // Get the last index of the last forward slash in the path
    int lastSlashIndex = path.lastIndexOf("/");

    // If there is no slash in the path, return the relative path with leading slash
    if (lastSlashIndex == -1) {
        return "/" + relativePath;
    }

    // Replace the last forward slash in the path with "/" followed by the relative path
    path = path.substring(0, lastSlashIndex) + "/" + relativePath;

    return path;
}

