void function(JTable table, int row, JScrollPane pane) {
    if (table == null || pane == null) {
        return;
    }

    int rowCount = table.getRowCount();
    if (row < 0 || row >= rowCount) {
        // Handle invalid row index
        throw new IllegalArgumentException("Invalid row index: " + row);
    }

    table.getSelectionModel().setSelectionInterval(row, row);
    pane.scrollToRow(row);
    table.invalidate(); // Delayed repaint, allowing the table to paint the newly selected row
    pane.revalidate();
}

public static void selectRow(int row, JTable table, JScrollPane pane) {
    if (table == null || pane == null) {
        return;
    }

    row = Math.max(0, Math.min(row, table.getRowCount() - 1));
    pane.getVerticalScrollBar().setValue(pane.getVerticalScrollBar().getValue() + (table.getRowHeight() * row));
    try {
        Thread.sleep(50); // Let the table repaint
        pane.repaint();
    } catch (InterruptedException e) {
        e.printStackTrace();
    }
