    if (timeBucket < 0) {
        throw new IllegalArgumentException("timeBucket cannot be negative");
    }
    if (dayStep <= 0) {
        throw new IllegalArgumentException("dayStep cannot be zero or negative");
    }

    long normalizedYear = timeBucket / (100 * 365 * 24); // assuming year has 365 days and there are 24 hours in a day
      long normalizedMonth = (timeBucket - normalizedYear * (100 * 365 * 24)) / (30 * 24); // assuming month has 30 days
      long normalizedDay = (timeBucket - normalizedYear * (100 * 365 * 24) - normalizedMonth * (30 * 24)) / 24;
      long newDay = (int) ((normalizedDay + 1) / dayStep) * dayStep;

    return normalizedYear * (100 * 365 * 24) + normalizedMonth * (30 * 24) + newDay;
}

public static long compressTimeBucket(long timeBucket, int dayStep) {
    // Validate input parameters
    if (timeBucket == Long.MIN_VALUE || timeBucket == Long.MAX_VALUE) {
        throw new IllegalArgumentException("timeBucket is out of bounds");
    }
    if (dayStep <= 0) {
        throw new IllegalArgumentException("dayStep must be positive");
    }

    long result = timeBucket;
    int year = (int) (timeBucket / (1000 * 60 * 60 * 24 * 365));
    int month = (int) ((timeBucket - (year * 1000 * 60 * 60 * 24 * 365)) / (1000 * 60 * 60 * 24 * 7));
    int day = (int) ((timeBucket - (year * 1000 * 60 * 60 * 24 * 365) - (month * 1000 * 60 * 60 * 24 * 7)) / (1000 * 60 * 60 * 24));

    // Adjust day based on dayStep
    day = Math.floorMod(day, dayStep) + 1;

    // Calculate Reformatted Year, Month, Day
    long reformattedYear = year + (day / dayStep);
    long reformattedMonth = month + (long) ((day - (day / dayStep)) / 7);
    long reformattedDay = (long) ((day - (day / dayStep)) % 7);

    result = (reformattedYear * 1000 * 60 * 60 * 24 * 365) + (reformattedMonth * 1000 * 60 * 60 * 24 * 7) + reformattedDay;

    return result;
}

